// Imported style library, rebuilt for the current grid. Pure.
//
// library-data.js (generated by scripts/import-library.mjs) stores each measurement
// relative to the grid it was designed on. Here they become points again:
//   { size }  × body point size (point sizes round to 0.1 pt)
//   { lines } × corrected leading
//   { units } × grid unit
// so the styles keep their proportions to the type and the grid at any setting.

import { mmToPt } from './grid.js';
import { LIBRARY } from './library-data.js';

export { LIBRARY };

const round = (v, dp) => Math.round(v * 10 ** dp) / 10 ** dp;

/** The scale factors for a computed grid. */
export function libraryScale(grid) {
  return {
    bodySize: grid.input.fontSize,
    leadingPt: grid.type.correctedLeadingPt,
    unitPt: mmToPt(grid.grid.unitMm),
  };
}

/** One stored value → a plain value for this grid (numbers in pt). */
export function resolveValue(v, key, scale) {
  if (v === null || typeof v !== 'object') return v;
  if ('size' in v) return key === 'PointSize' ? round(v.size * scale.bodySize, 1) : round(v.size * scale.bodySize, 8);
  if ('lines' in v) return round(v.lines * scale.leadingPt, 8);
  if ('units' in v) return round(v.units * scale.unitPt, 8);
  return v;
}

/**
 * Every imported style with its attributes resolved for `grid`.
 * Each: { kind, name, attrs: {k: string|number}, properties: [{ tag, value } | { raw } | { tag:'TabList', tabs }] }
 */
export function resolveLibrary(grid, library = LIBRARY) {
  const scale = libraryScale(grid);
  const one = (s) => ({
    kind: s.kind,
    name: s.name,
    attrs: Object.fromEntries(Object.entries(s.attrs).map(([k, v]) => [k, resolveValue(v, k, scale)])),
    properties: s.properties.map((p) => {
      if (p.tag === 'TabList') return { tag: 'TabList', tabs: p.tabs.map((t) => ({ raw: t.raw, position: t.units == null ? null : resolveValue({ units: t.units }, 'Position', scale) })) };
      if (p.tag) return { tag: p.tag, value: resolveValue(p, p.tag, scale) };
      return p;
    }),
  });
  return {
    scale,
    source: library.source,
    colours: library.colours,
    paragraph: library.paragraph.map(one),
    character: library.character.map(one),
    table: library.table.map(one).map((t) => fitTableToRows(t, grid)),
    cell: library.cell.map(one),
    object: library.object.map(one),
    defaults: library.defaults,
  };
}

/**
 * Tables step down the page grid one row at a time: no space before, and the row
 * gutter after, so a table that fills a grid row ends on the row's bottom edge and
 * the next one starts on the next row's top edge. (Row heights can't live in a
 * style; the table's own rows decide whether it fills a grid row.)
 */
export function fitTableToRows(t, grid) {
  return { ...t, attrs: { ...t.attrs, SpaceBefore: 0, SpaceAfter: round(mmToPt(grid.rows.gutter), 8) } };
}

/** A resolved paragraph or character style by name (with or without its group prefix). */
export function findLibraryStyle(resolved, kind, name) {
  return resolved[kind].find((s) => s.name === name || s.name.endsWith(`:${name}`)) ?? null;
}
